let gigroupInstallPrompt=null;
function pwaIsInstalled(){return !!window.matchMedia?.('(display-mode: standalone)').matches||(typeof navigator!=='undefined'&&navigator.standalone===true)}
function updatePWAInstallUI(){const button=document.getElementById('pwainstall');if(!button)return;button.classList.toggle('hidden',pwaIsInstalled())}
function updatePWAConnection(){const label=document.getElementById('pwaconnection');if(label&&typeof navigator!=='undefined')label.textContent=navigator.onLine?'':'Offline — local records only'}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();gigroupInstallPrompt=event;updatePWAInstallUI()});
window.addEventListener('appinstalled',()=>{gigroupInstallPrompt=null;document.getElementById('pwainstall')?.classList.add('hidden');toast('GIGROUP app installed.')});
window.addEventListener('online',updatePWAConnection);window.addEventListener('offline',updatePWAConnection);
async function installGIGROUPApp(){if(pwaIsInstalled())return;if(gigroupInstallPrompt){const prompt=gigroupInstallPrompt;gigroupInstallPrompt=null;try{await prompt.prompt();await prompt.userChoice}catch{showPWAInstallSteps()}return}showPWAInstallSteps()}
function showPWAInstallSteps(){const ios=/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);document.getElementById('installappsteps').innerHTML=ios?'<p>On iPhone / iPad:</p><ol><li>Open this CRM in Safari.</li><li>Tap the <strong>Share</strong> button.</li><li>Choose <strong>Add to Home Screen</strong>, then <strong>Add</strong>.</li></ol>':'<p>On Android:</p><ol><li>Open this CRM in Chrome and sign in if asked.</li><li>Tap the browser menu <strong>⋮</strong>.</li><li>Choose <strong>Install app</strong> or <strong>Add to Home screen</strong>.</li></ol><p>On a computer, look for the install option in the browser address bar or menu.</p>';document.getElementById('installappdialog').showModal()}
window.addEventListener('load',()=>{updatePWAInstallUI();updatePWAConnection();if('serviceWorker' in navigator&&window.isSecureContext)navigator.serviceWorker.register('/sw.js',{scope:'/',updateViaCache:'none'}).catch(()=>{ /* Browser-menu installation remains available; no false offline claim. */ })});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.body?.classList.contains('draweropen'))closeMobileNavigation()});
